using System;using System.IO;using System.Threading.Tasks;
static class AtomicPathChecks {
 static void Main(string[] args){string folder=Path.GetFullPath(args[0]);while(folder.Length<178){int n=Math.Min(25,179-folder.Length);folder=Path.Combine(folder,new string('d',n));}Directory.CreateDirectory(folder);string file=Path.Combine(folder,"command-"+DateTime.UtcNow.Ticks+"-"+Guid.NewGuid()+".json");if(file.Length>=260||file.Length+38<260)throw new Exception("Fixture does not reproduce temporary-name overflow");JagoHostSecurity.Atomic(file,"first");if(File.ReadAllText(file)!="first")throw new Exception("Long command create failed");JagoHostSecurity.Atomic(file,"replacement");if(File.ReadAllText(file)!="replacement")throw new Exception("Long command replace failed");Parallel.For(0,32,i=>JagoHostSecurity.Atomic(file,"writer-"+i+"-"+new string('x',8192)));if(!File.ReadAllText(file).StartsWith("writer-")||new FileInfo(file).Length<8192)throw new Exception("Concurrent writers lost data");if(Directory.GetFiles(folder,".jago-*.tmp").Length!=0)throw new Exception("Temporary file was not cleaned");Console.WriteLine("PASS: nested command create/replace, 32 concurrent writers and no orphan temp; target path "+file.Length+" chars");}
}
